-- Persian remains in the existing columns. Additive change; no existing copy is overwritten.
ALTER TABLE "contents" ADD COLUMN "translations" JSONB;

-- Initial English and Arabic editions of the current home page. Editors can change
-- them independently in the CMS. Restrict the backfill to the homeContent record.
UPDATE "contents"
SET "translations" = $translations$
{
  "en": {
    "title": "Home content",
    "small_text": "Rent villas, suites and stays across Iran",
    "full_text": "Rent directly from hosts — no commission, no middleman",
    "seo": {
      "metaTitle": "Rent villas, suites and stays across Iran",
      "metaDescription": "Find and book villas, suites and stays across Iran on Jayab. Contact hosts directly, with no commission or middleman, for a comfortable and confident trip."
    },
    "html": "<p>Travel always brings a fresh perspective. Sometimes you set off with excitement; at other times you look for a different destination to rest and unwind. Whether you want to <strong>rent a villa</strong> in northern Iran, book a villa in a popular tourist city or find a stay anywhere in Iran, Jayab helps you explore your options.</p><p>On Jayab, you can browse <strong>villas, suites and other stays</strong> with a range of prices and amenities. From luxury villas with pools to woodland cabins, traditional houses, eco-lodges and family suites, you can compare different types of accommodation in one place.</p><h2>A wide range of villas and stays</h2><p>If you are planning to rent a villa in northern Iran or book a stay by the sea, in a forest or in the mountains, Jayab offers hundreds of different options. Travelers looking for accommodation in cities across Iran can also explore budget, family and luxury stays.</p><p>Use the search filters to narrow your options by guest count, amenities, location and budget. Photos, detailed descriptions and reviews from previous guests help you choose a villa or suite with greater confidence.</p><h2>Book a villa or suite in a few clicks</h2><p>Finding and booking a villa or suite on Jayab is designed to be simple. Choose your destination to see the available villas, suites and other stays, then compare amenities, prices and locations to find the option that suits your trip.</p><p>Whether you need a villa for a family holiday or a suite for a business trip, Jayab gives you access to different stays across the country. Explore popular destinations in northern Iran as well as places to visit in the south, west and east.</p><h2>Why choose Jayab for your next stay?</h2><p>Jayab aims to make renting and booking accommodation a straightforward and reliable experience. Listings include detailed information, quality photos and descriptions of the amenities so you can make an informed choice.</p><p>If you are looking for a suite in a tourist destination or accommodation for a short trip, you can compare hundreds of options. Clear information and price comparisons help you decide which villa, suite or other stay is right for you.</p><h2>How to find the right accommodation</h2><p>Start by searching for your destination or preferred type of accommodation. Use the filters to find suitable villas, suites or other stays and compare your options. Review the photos, amenities and guest feedback before completing your booking.</p><h2>Find and book your next stay</h2><p>Whether you are planning a trip to northern Iran or another part of the country, Jayab helps you find villas, suites and other stays. Choose your destination, explore the available accommodation and book the place that suits your trip for a relaxing and memorable journey.</p>"
  },
  "ar": {
    "title": "محتوى الصفحة الرئيسية",
    "small_text": "استئجار الفلل والأجنحة وأماكن الإقامة في أنحاء إيران",
    "full_text": "استأجر إقامتك مباشرة من المضيف، دون عمولة ودون وسيط",
    "seo": {
      "metaTitle": "استئجار الفلل والأجنحة وأماكن الإقامة في أنحاء إيران",
      "metaDescription": "اعثر على الفلل والأجنحة وأماكن الإقامة واحجزها في أنحاء إيران عبر جاياب. تواصل مباشرة مع المضيف دون عمولة أو وسيط لرحلة مريحة ومطمئنة."
    },
    "html": "<p>يحمل السفر دائما أجواء جديدة؛ فقد تنطلق بحماس لاكتشاف وجهة جديدة، أو تبحث عن مكان مختلف للراحة والاسترخاء. إذا كنت تفكر في <strong>استئجار فيلا</strong> في شمال إيران، أو حجز فيلا في إحدى المدن السياحية، أو العثور على مكان للإقامة في أي منطقة من إيران، يساعدك جاياب على استكشاف الخيارات المناسبة.</p><p>يمكنك في جاياب تصفح <strong>الفلل والأجنحة وأماكن الإقامة</strong> بأسعار ومرافق متنوعة. من الفلل الفاخرة المزودة بمسابح إلى الأكواخ وسط الغابات والبيوت التقليدية والنزل البيئية والأجنحة العائلية، تجد خيارات متعددة في منصة واحدة لتتمكن من المقارنة والاختيار بسهولة.</p><h2>خيارات واسعة من الفلل وأماكن الإقامة</h2><p>إذا كنت تخطط لاستئجار فيلا في شمال إيران أو حجز إقامة قرب البحر أو وسط الغابات أو في الجبال، يقدم لك جاياب مئات الخيارات المتنوعة. ويمكن للباحثين عن الإقامة في مختلف مدن إيران استكشاف أماكن اقتصادية وعائلية وفاخرة.</p><p>استخدم مرشحات البحث لتحديد الخيارات حسب عدد الضيوف والمرافق والموقع والميزانية. تساعدك الصور والأوصاف المفصلة وتقييمات الضيوف السابقين على اختيار الفيلا أو الجناح بثقة أكبر.</p><h2>حجز فيلا أو جناح بخطوات بسيطة</h2><p>صممت تجربة البحث والحجز في جاياب لتكون سهلة. اختر وجهتك للاطلاع على الفلل والأجنحة وأماكن الإقامة المتاحة، ثم قارن المرافق والأسعار والمواقع للعثور على الخيار الذي يناسب رحلتك.</p><p>سواء كنت تبحث عن فيلا لقضاء عطلة عائلية أو جناح لرحلة عمل، يتيح لك جاياب الوصول إلى أماكن إقامة متنوعة في أنحاء البلاد. استكشف الوجهات الشهيرة في شمال إيران، إلى جانب الوجهات السياحية في الجنوب والغرب والشرق.</p><h2>لماذا تختار جاياب لإقامتك القادمة؟</h2><p>يسعى جاياب إلى جعل استئجار أماكن الإقامة وحجزها تجربة سهلة وموثوقة. تتضمن الإعلانات معلومات مفصلة وصورا عالية الجودة ووصفا للمرافق لتتمكن من اتخاذ قرار مناسب.</p><p>إذا كنت تبحث عن جناح في وجهة سياحية أو مكان للإقامة خلال رحلة قصيرة، يمكنك المقارنة بين مئات الخيارات. تساعدك المعلومات الواضحة ومقارنة الأسعار على تحديد الفيلا أو الجناح أو مكان الإقامة الأنسب لك.</p><h2>كيف تجد مكان الإقامة المناسب؟</h2><p>ابدأ بالبحث عن وجهتك أو نوع الإقامة المفضل لديك. استخدم المرشحات للعثور على الفلل والأجنحة وأماكن الإقامة المناسبة وقارن بينها. اطلع على الصور والمرافق وتقييمات الضيوف قبل إتمام الحجز.</p><h2>اعثر على إقامتك القادمة واحجزها</h2><p>سواء كنت تخطط لزيارة شمال إيران أو أي منطقة أخرى من البلاد، يساعدك جاياب على العثور على الفلل والأجنحة وأماكن الإقامة. اختر وجهتك واستكشف الخيارات المتاحة واحجز المكان المناسب لرحلتك لتستمتع بسفر مريح وذكريات جميلة.</p>"
  }
}
$translations$::jsonb
WHERE "key" = 'homeContent' AND "translations" IS NULL;
